            if(it%2==0)
                sum+=it;
        }
        for(auto it:queries)
        {
            int val=it[0];
            int idx=it[1];
            if(nums[idx]%2==0)
                sum-=nums[idx];
            nums[idx]+=val;
            if(nums[idx]%2==0)
                sum+=nums[idx];
            ans.push_back(sum);
        }
